def _text(value: Any, field_name: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise ValueError(f"{field_name} must be a non-empty, trimmed string")
    if "\x00" in value:
        raise ValueError(f"{field_name} must not contain NUL")
    return value


def _optional_text(value: Any, field_name: str) -> str | None:
    if value is None:
        return None
    return _text(value, field_name)


def _sha256(value: Any, field_name: str) -> str:
    result = _text(value, field_name)
    if not _SHA256_RE.fullmatch(result):
        raise ValueError(f"{field_name} must be a lowercase SHA-256 digest")
    return result


def _optional_sha256(value: Any, field_name: str) -> str | None:
    if value is None:
        return None
    return _sha256(value, field_name)


def _utc(value: Any, field_name: str) -> datetime:
    if not isinstance(value, datetime):
        raise TypeError(f"{field_name} must be datetime")
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError(f"{field_name} must be timezone-aware")
    return value.astimezone(timezone.utc)


def _iso(value: datetime) -> str:
    return _utc(value, "timestamp").isoformat(timespec="microseconds").replace(
        "+00:00", "Z"
    )


def _parse_iso(value: str, field_name: str) -> datetime:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be an ISO-8601 string")
    encoded = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        parsed = datetime.fromisoformat(encoded)
    except ValueError as error:
        raise ValueError(f"{field_name} must be an ISO-8601 timestamp") from error
    return _utc(parsed, field_name)


def _exact_decimal(
    value: Any,
    field_name: str,
    *,
    positive: bool = False,
    nonnegative: bool = False,
    optional: bool = False,
) -> Decimal | None:
    if value is None and optional:
        return None
    if isinstance(value, (float, bool)):
        raise TypeError(f"{field_name} must be Decimal, int, or exact string; floats are forbidden")
    if isinstance(value, Decimal):
        result = value
    elif isinstance(value, int):
        result = Decimal(value)
    elif isinstance(value, str):
        if not value or value != value.strip():
            raise ValueError(f"{field_name} must be a trimmed exact decimal")
        try:
            result = Decimal(value)
        except InvalidOperation as error:
            raise ValueError(f"{field_name} is not an exact decimal") from error
    else:
        raise TypeError(f"{field_name} must be Decimal, int, or exact string")
    validate_decimal_bounds(result, field=field_name)
    if positive and result <= 0:
        raise ValueError(f"{field_name} must be greater than zero")
    if nonnegative and result < 0:
        raise ValueError(f"{field_name} must be non-negative")
    return result


def _ratio(numerator: Decimal, denominator: Decimal) -> Decimal:
    if denominator == 0:
        raise ValueError("ratio denominator must not be zero")
    with localcontext() as context:
        context.prec = 50
        result = numerator / denominator
    validate_decimal_bounds(result, field="derived ratio")
    return result


def _add_exact(*values: Decimal) -> Decimal:
    with localcontext() as context:
        context.prec = 256
        return sum(values, Decimal(0))


def _subtract_exact(left: Decimal, right: Decimal) -> Decimal:
    with localcontext() as context:
        context.prec = 256
        return left - right


def _multiply_exact(left: Decimal, right: Decimal) -> Decimal:
    with localcontext() as context:
        context.prec = 256
        return left * right


def _sum_exact(values: Iterable[Decimal]) -> Decimal:
    with localcontext() as context:
        context.prec = 256
        return sum(values, Decimal(0))


def _enum(value: Any, enum_type: type[_StringEnum], field_name: str) -> _StringEnum:
    if isinstance(value, enum_type):
        return value
    if isinstance(value, str):
        try:
            return enum_type(value)
        except ValueError as error:
            raise ValueError(f"invalid {field_name}: {value!r}") from error
    raise TypeError(f"{field_name} must be {enum_type.__name__} or str")


def _string_tuple(value: Iterable[str], field_name: str, *, empty_ok: bool = True) -> tuple[str, ...]:
    if isinstance(value, str):
        raise TypeError(f"{field_name} must be an iterable of strings, not str")
    result = tuple(_text(item, field_name) for item in value)
    if not empty_ok and not result:
        raise ValueError(f"{field_name} must not be empty")
    if len(set(result)) != len(result):
        raise ValueError(f"{field_name} must not contain duplicates")
    return result


@dataclass(frozen=True, slots=True)
class SourceEvidence:
    """Hash-only reference to TA, sentiment, market, or availability evidence."""

    source_id: str
    source_kind: str
    content_hash: str
    observed_at: datetime
    captured_at: datetime
    source_version: str
    locator: str | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "source_id", _text(self.source_id, "source_id"))
        object.__setattr__(self, "source_kind", _text(self.source_kind, "source_kind"))
        object.__setattr__(self, "content_hash", _sha256(self.content_hash, "content_hash"))
        object.__setattr__(self, "observed_at", _utc(self.observed_at, "observed_at"))
        object.__setattr__(self, "captured_at", _utc(self.captured_at, "captured_at"))
        object.__setattr__(self, "source_version", _text(self.source_version, "source_version"))
        object.__setattr__(self, "locator", _optional_text(self.locator, "locator"))
        if self.captured_at < self.observed_at:
            raise ValueError("captured_at must not precede observed_at")


@dataclass(frozen=True, slots=True)
class ComponentVersions:
    """Exact versions responsible for a decision."""

    strategy_version: str
    configuration_version: str
    code_hash: str
    decision_rule_version: str
    ta_version: str
    sentiment_version: str
    risk_policy_version: str

    def __post_init__(self) -> None:
        for name in (
            "strategy_version",
            "configuration_version",
            "decision_rule_version",
            "ta_version",
            "sentiment_version",
            "risk_policy_version",
        ):
            object.__setattr__(self, name, _text(getattr(self, name), name))
        object.__setattr__(self, "code_hash", _sha256(self.code_hash, "code_hash"))


@dataclass(frozen=True, slots=True)
class ProposedBracket:
    """Proposed position economics; a stop is structurally mandatory."""

    side: DecisionClass
    entry_price: Decimal
    stop_price: Decimal
    target_price: Decimal
    quantity: Decimal
    risk_amount: Decimal
    settlement_asset: str
    planned_reward_risk: Decimal = field(init=False)

    def __post_init__(self) -> None:
        side = _enum(self.side, DecisionClass, "side")
        if side not in (DecisionClass.BUY, DecisionClass.SELL):
            raise ValueError("bracket side must be buy or sell")
        object.__setattr__(self, "side", side)
        for name in ("entry_price", "stop_price", "target_price", "quantity", "risk_amount"):
            object.__setattr__(
                self,
                name,
                _exact_decimal(getattr(self, name), name, positive=True),
            )
        object.__setattr__(
            self, "settlement_asset", _text(self.settlement_asset, "settlement_asset").upper()
        )
        if side is DecisionClass.BUY:
            if not self.stop_price < self.entry_price < self.target_price:
                raise ValueError("buy bracket requires stop < entry < target")
            reward = _subtract_exact(self.target_price, self.entry_price)
            risk = _subtract_exact(self.entry_price, self.stop_price)
        else:
            if not self.target_price < self.entry_price < self.stop_price:
                raise ValueError("sell bracket requires target < entry < stop")
            reward = _subtract_exact(self.entry_price, self.target_price)
            risk = _subtract_exact(self.stop_price, self.entry_price)
        object.__setattr__(self, "planned_reward_risk", _ratio(reward, risk))


@dataclass(frozen=True, slots=True)
class DecisionCycle:
    """One scheduled decision, including abstentions and unavailable cycles."""

    cycle_id: str
    asset: str
    instrument: str
    venue: str
    environment: str
    timeframe: str
    decided_at: datetime
    classification: DecisionClass
    rationale_code: str
    thesis_hash: str
    versions: ComponentVersions
    evidence: tuple[SourceEvidence, ...]
    confidence: Decimal | None = None
    bracket: ProposedBracket | None = None
    tags: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        for name in ("cycle_id", "asset", "instrument", "venue", "environment", "timeframe", "rationale_code"):
            value = _text(getattr(self, name), name)
            if name == "asset":
                value = value.upper()
            object.__setattr__(self, name, value)
        object.__setattr__(self, "decided_at", _utc(self.decided_at, "decided_at"))
        classification = _enum(self.classification, DecisionClass, "classification")
        object.__setattr__(self, "classification", classification)
        object.__setattr__(self, "thesis_hash", _sha256(self.thesis_hash, "thesis_hash"))
        if not isinstance(self.versions, ComponentVersions):
            raise TypeError("versions must be ComponentVersions")
        evidence = tuple(self.evidence)
        if not evidence or not all(isinstance(item, SourceEvidence) for item in evidence):
            raise ValueError("evidence must contain at least one SourceEvidence")
        if len({item.source_id for item in evidence}) != len(evidence):
            raise ValueError("evidence source_id values must be unique")
        if any(item.captured_at > self.decided_at for item in evidence):
            raise ValueError("decision evidence cannot be captured after decided_at")
        object.__setattr__(
            self,
            "evidence",
            tuple(sorted(evidence, key=lambda item: (item.source_id, item.content_hash))),
        )
        confidence = _exact_decimal(
            self.confidence, "confidence", nonnegative=True, optional=True
        )
        if confidence is not None and confidence > 1:
            raise ValueError("confidence must be between zero and one")
        object.__setattr__(self, "confidence", confidence)
        object.__setattr__(self, "tags", tuple(sorted(_string_tuple(self.tags, "tags"))))
        if classification in (DecisionClass.BUY, DecisionClass.SELL):
            if not isinstance(self.bracket, ProposedBracket):
                raise ValueError("buy/sell decisions require a proposed bracket with stop")
            if self.bracket.side is not classification:
                raise ValueError("bracket side must match decision classification")
        elif self.bracket is not None:
            raise ValueError("nothing/unavailable decisions must not propose a position")


