@dataclass(frozen=True, slots=True)
class CounterfactualSpec:
    scenario_id: str
    side: DecisionClass
    entry_price: Decimal
    stop_price: Decimal
    target_price: Decimal
    entry_rule: "CounterfactualEntryRule"
    cost_r: Decimal
    max_bars: int
    scenario_version: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "scenario_id", _text(self.scenario_id, "scenario_id"))
        side = _enum(self.side, DecisionClass, "side")
        if side not in (DecisionClass.BUY, DecisionClass.SELL):
            raise ValueError("counterfactual side must be buy or sell")
        object.__setattr__(self, "side", side)
        object.__setattr__(
            self,
            "entry_rule",
            _enum(self.entry_rule, CounterfactualEntryRule, "entry_rule"),
        )
        for name in ("entry_price", "stop_price", "target_price"):
            object.__setattr__(self, name, _exact_decimal(getattr(self, name), name, positive=True))
        object.__setattr__(self, "cost_r", _exact_decimal(self.cost_r, "cost_r", nonnegative=True))
        if isinstance(self.max_bars, bool) or not isinstance(self.max_bars, int) or self.max_bars <= 0:
            raise ValueError("max_bars must be a positive integer")
        object.__setattr__(self, "scenario_version", _text(self.scenario_version, "scenario_version"))
        if side is DecisionClass.BUY:
            valid = self.stop_price < self.entry_price < self.target_price
        else:
            valid = self.target_price < self.entry_price < self.stop_price
        if not valid:
            raise ValueError("counterfactual bracket is invalid for side")


@dataclass(frozen=True, slots=True)
class LedgerEvent:
    sequence: int
    event_id: str
    event_type: str
    cycle_id: str
    semantic_key: str
    idempotency_key: str
    occurred_at: datetime
    recorded_at: datetime
    payload: Mapping[str, Any]
    content_hash: str
    previous_hash: str
    event_hash: str
    schema_version: int


class LearningLedger:
    """Atomic append-only learning ledger backed by one local SQLite file."""

    def __init__(
        self,
        path: str | Path,
        *,
        clock: Callable[[], datetime] | None = None,
        must_exist: bool = False,
    ) -> None:
        if str(path) == ":memory:":
            raise ValueError("learning ledger must be file-backed; :memory: is forbidden")
        self.path = Path(path)
        if self.path.exists() and self.path.is_dir():
            raise ValueError("ledger path must be a file, not a directory")
        if type(must_exist) is not bool:
            raise TypeError("must_exist must be a boolean")
        self._must_exist = must_exist
        if not must_exist:
            self.path.parent.mkdir(parents=True, exist_ok=True)
        self._clock = clock or (lambda: datetime.now(timezone.utc))
        self._initialize()
        if not must_exist:
            self.verify_integrity()

    def _connect(
        self,
        *,
        read_only: bool = False,
        verification_path: Path | None = None,
    ) -> sqlite3.Connection:
        database_path = self.path if verification_path is None else verification_path
        database: str | Path = database_path
        if read_only:
            database = f"{database_path.absolute().as_uri()}?mode=ro"
        elif self._must_exist:
            database = f"{self.path.absolute().as_uri()}?mode=rw"
        connection = sqlite3.connect(
            database,
            timeout=30,
            isolation_level=None,
            uri=read_only or self._must_exist,
        )
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA foreign_keys = ON")
        connection.execute("PRAGMA busy_timeout = 30000")
        if read_only:
            connection.execute("PRAGMA query_only = ON")
        else:
            try:
                validate_sqlite_file_sizes(
                    self.path,
                    max_bytes=MAX_SHARED_STATE_FILE_BYTES,
                )
            except StorageError as error:
                connection.close()
                raise LedgerIntegrityError(str(error)) from error
        return connection

    def _initialize(self) -> None:
        if self._must_exist:
            self._verify_existing()
            return
        with closing(self._connect()) as connection:
            connection.execute("PRAGMA journal_mode = WAL")
            connection.executescript(
                """
                CREATE TABLE IF NOT EXISTS learning_ledger_meta (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL
                ) WITHOUT ROWID;

                CREATE TABLE IF NOT EXISTS learning_ledger_events (
                    sequence INTEGER PRIMARY KEY,
                    event_id TEXT NOT NULL UNIQUE,
                    event_type TEXT NOT NULL,
                    cycle_id TEXT NOT NULL,
                    semantic_key TEXT NOT NULL,
                    idempotency_key TEXT NOT NULL UNIQUE,
                    occurred_at TEXT NOT NULL,
                    recorded_at TEXT NOT NULL,
                    payload_json TEXT NOT NULL,
                    content_hash TEXT NOT NULL,
                    previous_hash TEXT NOT NULL,
                    event_hash TEXT NOT NULL UNIQUE,
                    schema_version INTEGER NOT NULL,
                    UNIQUE(event_type, semantic_key)
                );

                CREATE INDEX IF NOT EXISTS learning_ledger_cycle_sequence
                    ON learning_ledger_events(cycle_id, sequence);

                CREATE TRIGGER IF NOT EXISTS learning_ledger_no_update
                BEFORE UPDATE ON learning_ledger_events
                BEGIN
                    SELECT RAISE(ABORT, 'learning ledger events are immutable');
                END;

                CREATE TRIGGER IF NOT EXISTS learning_ledger_no_delete
                BEFORE DELETE ON learning_ledger_events
                BEGIN
                    SELECT RAISE(ABORT, 'learning ledger events are immutable');
                END;
                """
            )
            existing = connection.execute(
                "SELECT value FROM learning_ledger_meta WHERE key = 'schema_version'"
            ).fetchone()
            if existing is None:
                connection.execute(
                    "INSERT INTO learning_ledger_meta(key, value) VALUES ('schema_version', ?)",
                    (str(LEDGER_SCHEMA_VERSION),),
                )
            elif existing["value"] != str(LEDGER_SCHEMA_VERSION):
                raise LedgerIntegrityError("unsupported learning ledger schema version")

    def _verify_existing(self) -> None:
        try:
            with sqlite_verification_snapshot(
                self.path,
                label="learning ledger database",
                max_bytes=MAX_SHARED_STATE_FILE_BYTES,
            ) as snapshot:
                with closing(
                    self._connect(
                        read_only=True,
                        verification_path=snapshot.database,
                    )
                ) as connection:
                    query_only = connection.execute("PRAGMA query_only").fetchone()
                    if query_only is None or int(query_only[0]) != 1:
                        raise LedgerIntegrityError(
                            "learning ledger verification is not query-only"
                        )
                    mode = connection.execute("PRAGMA journal_mode").fetchone()
                    if mode is None or str(mode[0]).lower() != "wal":
                        raise LedgerIntegrityError(
                            "learning ledger database is not in WAL mode"
                        )
                    quick_check = connection.execute("PRAGMA quick_check").fetchall()
                    if not quick_check or any(
                        str(row[0]).lower() != "ok" for row in quick_check
                    ):
                        raise LedgerIntegrityError(
                            "learning ledger database integrity check failed"
                        )
                    self._verify_schema_locked(connection)
                    self._verify_integrity_locked(connection)
        except LedgerIntegrityError:
            raise
        except StorageError as error:
            raise LedgerIntegrityError(str(error)) from error
        except sqlite3.Error as error:
            raise LedgerIntegrityError(
                f"learning ledger verification failed: {type(error).__name__}"
            ) from error

    @staticmethod
    def _verify_schema_locked(connection: sqlite3.Connection) -> None:
        for table, expected_columns in _EXPECTED_LEDGER_COLUMNS.items():
            actual_columns = tuple(
                str(row["name"])
                for row in connection.execute(f'PRAGMA table_info("{table}")')
            )
            if actual_columns != expected_columns:
                raise LedgerIntegrityError(
                    f"learning ledger table {table} has an unexpected schema"
                )
        rows = connection.execute(
            """
            SELECT name, sql FROM sqlite_master
            WHERE type IN ('table', 'index', 'trigger', 'view')
              AND name NOT LIKE 'sqlite_%'
              AND sql IS NOT NULL
            """
        ).fetchall()
        actual_sql = {
            str(row["name"]): _normalized_schema_sql(row["sql"]) for row in rows
        }
        expected_sql = {
            name: _normalized_schema_sql(sql)
            for name, sql in _EXPECTED_LEDGER_SCHEMA_SQL.items()
        }
        expected_with_binding = {
            **expected_sql,
            STATE_BINDING_TABLE: _normalized_schema_sql(STATE_BINDING_TABLE_SQL),
        }
        if actual_sql not in (expected_sql, expected_with_binding):
            raise LedgerIntegrityError(
                "learning ledger tables, indexes, or immutability triggers do not match"
            )
        metadata = connection.execute(
            "SELECT key, value FROM learning_ledger_meta ORDER BY key"
        ).fetchall()
        if len(metadata) != 1 or (
            metadata[0]["key"] != "schema_version"
            or metadata[0]["value"] != str(LEDGER_SCHEMA_VERSION)
        ):
            raise LedgerIntegrityError("unsupported learning ledger schema metadata")

    def verify_integrity(self) -> str:
        """Verify every persisted event and return the current chain head."""

        with closing(self._connect()) as connection:
            return self._verify_integrity_locked(connection)

    def _verify_integrity_locked(self, connection: sqlite3.Connection) -> str:
        previous = LEDGER_GENESIS_HASH
        previous_recorded_at: datetime | None = None
        expected_sequence = 1
        rows = connection.execute(
            "SELECT * FROM learning_ledger_events ORDER BY sequence"
        ).fetchall()
        for row in rows:
            if row["sequence"] != expected_sequence:
                raise LedgerIntegrityError("learning ledger sequence is not contiguous")
            if row["schema_version"] != EVENT_SCHEMA_VERSION:
                raise LedgerIntegrityError("unsupported event schema version")
            if row["previous_hash"] != previous:
                raise LedgerIntegrityError("learning ledger previous hash mismatch")
            try:
                payload = json.loads(row["payload_json"])
            except (TypeError, json.JSONDecodeError) as error:
                raise LedgerIntegrityError("learning ledger payload is not valid JSON") from error
            if canonical_json(payload) != row["payload_json"]:
                raise LedgerIntegrityError("learning ledger payload is not canonical JSON")
            content = self._event_content(
                event_type=row["event_type"],
                cycle_id=row["cycle_id"],
                semantic_key=row["semantic_key"],
                idempotency_key=row["idempotency_key"],
                occurred_at=row["occurred_at"],
                payload=payload,
            )
            content_hash = domain_hash(EVENT_CONTENT_DOMAIN, content)
            if content_hash != row["content_hash"]:
                raise LedgerIntegrityError("learning ledger content hash mismatch")
            event_id = domain_hash(
                EVENT_ID_DOMAIN,
                {"content_hash": content_hash, "idempotency_key": row["idempotency_key"]},
            )
            if event_id != row["event_id"]:
                raise LedgerIntegrityError("learning ledger event id mismatch")
            event_hash = domain_hash(
                EVENT_CHAIN_DOMAIN,
                {
                    "sequence": row["sequence"],
                    "event_id": event_id,
                    "content_hash": content_hash,
                    "recorded_at": row["recorded_at"],
                    "previous_hash": previous,
                },
            )
            if event_hash != row["event_hash"]:
                raise LedgerIntegrityError("learning ledger event hash mismatch")
            _parse_iso(row["occurred_at"], "occurred_at")
            recorded_at = _parse_iso(row["recorded_at"], "recorded_at")
            if previous_recorded_at is not None and recorded_at < previous_recorded_at:
                raise LedgerIntegrityError("learning ledger recorded_at order regressed")
            previous = event_hash
            previous_recorded_at = recorded_at
            expected_sequence += 1
        return previous

    @staticmethod
    def _event_content(
        *,
        event_type: str,
        cycle_id: str,
        semantic_key: str,
        idempotency_key: str,
        occurred_at: str,
        payload: Mapping[str, Any],
    ) -> dict[str, Any]:
        return {
            "schema_version": EVENT_SCHEMA_VERSION,
            "event_type": event_type,
            "cycle_id": cycle_id,
            "semantic_key": semantic_key,
            "idempotency_key": idempotency_key,
            "occurred_at": occurred_at,
            "payload": payload,
        }

    def _append(
        self,
        *,
        event_type: str,
        cycle_id: str,
        semantic_key: str,
        idempotency_key: str,
        occurred_at: datetime,
        payload: Any,
        locked_validator: Callable[[sqlite3.Connection], None] | None = None,
    ) -> LedgerEvent:
        event_type = _text(event_type, "event_type")
        cycle_id = _text(cycle_id, "cycle_id")
        semantic_key = _text(semantic_key, "semantic_key")
        idempotency_key = _text(idempotency_key, "idempotency_key")
        occurred_at = _utc(occurred_at, "occurred_at")
        payload_data = canonical_data(payload)
        if not isinstance(payload_data, Mapping):
            raise TypeError("event payload must canonicalize to a mapping")
        payload_json = canonical_json(payload_data)
        if len(payload_json.encode("utf-8")) > MAX_LEARNING_EVENT_BYTES:
            raise LearningLedgerError("learning event payload exceeds its size limit")
        occurred_text = _iso(occurred_at)
        content = self._event_content(
            event_type=event_type,
            cycle_id=cycle_id,
            semantic_key=semantic_key,
            idempotency_key=idempotency_key,
            occurred_at=occurred_text,
            payload=payload_data,
        )
        content_hash = domain_hash(EVENT_CONTENT_DOMAIN, content)

        with closing(self._connect()) as connection:
            connection.execute("BEGIN IMMEDIATE")
            try:
                try:
                    enforce_sqlite_write_limit(
                        connection,
                        self.path,
                        max_bytes=MAX_SHARED_STATE_FILE_BYTES,
                        reserve_bytes=_LEARNING_WRITE_HEADROOM_BYTES,
                    )
                except StorageError as error:
                    raise LedgerIntegrityError(str(error)) from error
                previous = self._verify_integrity_locked(connection)
                existing = connection.execute(
                    "SELECT * FROM learning_ledger_events WHERE idempotency_key = ?",
                    (idempotency_key,),
                ).fetchone()
                if existing is not None:
                    if existing["content_hash"] != content_hash:
                        raise IdempotencyConflict(
                            f"idempotency key {idempotency_key!r} is bound to different content"
                        )
                    connection.commit()
                    return self._row_to_event(existing)

                if locked_validator is not None:
                    locked_validator(connection)

                duplicate = connection.execute(
                    "SELECT * FROM learning_ledger_events WHERE event_type = ? AND semantic_key = ?",
                    (event_type, semantic_key),
                ).fetchone()
                if duplicate is not None:
                    raise DuplicateConflict(
                        f"logical {event_type} record {semantic_key!r} already exists under another key"
                    )

                now = _utc(self._clock(), "ledger clock")
                head = connection.execute(
                    "SELECT sequence, recorded_at FROM learning_ledger_events ORDER BY sequence DESC LIMIT 1"
                ).fetchone()
                if head is not None and now < _parse_iso(head["recorded_at"], "recorded_at"):
                    raise LedgerBackdatingError("ledger clock moved behind the durable append head")
                if occurred_at > now:
                    raise LedgerBackdatingError("event occurred_at cannot be in the future")
                if (
                    event_type == "decision_cycle"
                    and now - occurred_at > MAX_DECISION_INGEST_LAG
                ):
                    raise LedgerBackdatingError(
                        "decision ingestion exceeded the prospective anti-backdating window"
                    )
                sequence = 1 if head is None else head["sequence"] + 1
                recorded_text = _iso(now)
                event_id = domain_hash(
                    EVENT_ID_DOMAIN,
                    {"content_hash": content_hash, "idempotency_key": idempotency_key},
                )
                event_hash = domain_hash(
                    EVENT_CHAIN_DOMAIN,
                    {
                        "sequence": sequence,
                        "event_id": event_id,
                        "content_hash": content_hash,
                        "recorded_at": recorded_text,
                        "previous_hash": previous,
                    },
                )
                connection.execute(
                    """
                    INSERT INTO learning_ledger_events(
                        sequence, event_id, event_type, cycle_id, semantic_key,
                        idempotency_key, occurred_at, recorded_at, payload_json,
                        content_hash, previous_hash, event_hash, schema_version
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        sequence,
                        event_id,
                        event_type,
                        cycle_id,
                        semantic_key,
                        idempotency_key,
                        occurred_text,
                        recorded_text,
                        payload_json,
                        content_hash,
                        previous,
                        event_hash,
                        EVENT_SCHEMA_VERSION,
                    ),
                )
                row = connection.execute(
                    "SELECT * FROM learning_ledger_events WHERE sequence = ?", (sequence,)
                ).fetchone()
                connection.commit()
                assert row is not None
                return self._row_to_event(row)
            except Exception:
                connection.rollback()
                raise

    def require_write_headroom(self) -> None:
        """Prove one bounded learning append can commit before entry dispatch."""

        with closing(self._connect()) as connection:
            connection.execute("BEGIN IMMEDIATE")
            try:
                enforce_sqlite_write_limit(
                    connection,
                    self.path,
                    max_bytes=MAX_SHARED_STATE_FILE_BYTES,
                    reserve_bytes=_LEARNING_WRITE_HEADROOM_BYTES,
                )
            except StorageError as error:
                raise LedgerIntegrityError(str(error)) from error
            finally:
                connection.rollback()

    @staticmethod
    def _row_to_event(row: sqlite3.Row) -> LedgerEvent:
        payload = json.loads(row["payload_json"])
        return LedgerEvent(
            sequence=row["sequence"],
            event_id=row["event_id"],
            event_type=row["event_type"],
            cycle_id=row["cycle_id"],
            semantic_key=row["semantic_key"],
            idempotency_key=row["idempotency_key"],
            occurred_at=_parse_iso(row["occurred_at"], "occurred_at"),
            recorded_at=_parse_iso(row["recorded_at"], "recorded_at"),
            payload=payload,
            content_hash=row["content_hash"],
            previous_hash=row["previous_hash"],
            event_hash=row["event_hash"],
            schema_version=row["schema_version"],
        )

    def events(self, *, cycle_id: str | None = None) -> tuple[LedgerEvent, ...]:
        """Read immutable events in chain order."""

        with closing(self._connect()) as connection:
            self._verify_integrity_locked(connection)
            if cycle_id is None:
                rows = connection.execute(
                    "SELECT * FROM learning_ledger_events ORDER BY sequence"
                ).fetchall()
            else:
                cycle_id = _text(cycle_id, "cycle_id")
                rows = connection.execute(
                    "SELECT * FROM learning_ledger_events WHERE cycle_id = ? ORDER BY sequence",
                    (cycle_id,),
                ).fetchall()
        return tuple(self._row_to_event(row) for row in rows)

    def _event_by_idempotency_key(self, idempotency_key: str) -> LedgerEvent | None:
        idempotency_key = _text(idempotency_key, "idempotency_key")
        with closing(self._connect()) as connection:
            self._verify_integrity_locked(connection)
            row = connection.execute(
                "SELECT * FROM learning_ledger_events WHERE idempotency_key = ?",
                (idempotency_key,),
            ).fetchone()
        return self._row_to_event(row) if row is not None else None

    def _cycle_events_locked(
        self, connection: sqlite3.Connection, cycle_id: str
    ) -> list[sqlite3.Row]:
        rows = connection.execute(
            "SELECT * FROM learning_ledger_events WHERE cycle_id = ? ORDER BY sequence",
            (cycle_id,),
        ).fetchall()
        if not rows or rows[0]["event_type"] != "decision_cycle":
            raise LifecycleError(f"decision cycle {cycle_id!r} does not exist")
        return rows

    def _cycle_events(self, cycle_id: str) -> tuple[LedgerEvent, ...]:
        events = self.events(cycle_id=cycle_id)
        if not events or events[0].event_type != "decision_cycle":
            raise LifecycleError(f"decision cycle {cycle_id!r} does not exist")
        return events

    @staticmethod
    def _decision_payload(events: Iterable[LedgerEvent]) -> Mapping[str, Any]:
        event = next((item for item in events if item.event_type == "decision_cycle"), None)
        if event is None:
            raise LifecycleError("decision event is missing")
        return event.payload

    @staticmethod
    def _require_after_decision(
        events: Iterable[LedgerEvent], timestamp: datetime, field_name: str
    ) -> None:
        decision = next(
            (item for item in events if item.event_type == "decision_cycle"), None
        )
        if decision is None:
            raise LifecycleError("decision event is missing")
        if timestamp < decision.occurred_at:
            raise LifecycleError(f"{field_name} must not precede the decision")

    @staticmethod
    def _locked_payloads(
        connection: sqlite3.Connection, cycle_id: str
    ) -> tuple[tuple[str, str, Mapping[str, Any]], ...]:
        rows = connection.execute(
            "SELECT event_type, event_hash, payload_json FROM learning_ledger_events "
            "WHERE cycle_id = ? ORDER BY sequence",
            (cycle_id,),
        ).fetchall()
        return tuple(
            (row["event_type"], row["event_hash"], json.loads(row["payload_json"]))
            for row in rows
        )

    def record_decision(self, cycle: DecisionCycle, *, idempotency_key: str) -> LedgerEvent:
        if not isinstance(cycle, DecisionCycle):
            raise TypeError("cycle must be DecisionCycle")
        return self._append(
            event_type="decision_cycle",
            cycle_id=cycle.cycle_id,
            semantic_key=cycle.cycle_id,
            idempotency_key=idempotency_key,
            occurred_at=cycle.decided_at,
            payload=cycle,
        )

    def record_approval(
        self, reference: ApprovalReference, *, idempotency_key: str
    ) -> LedgerEvent:
        if not isinstance(reference, ApprovalReference):
            raise TypeError("reference must be ApprovalReference")
        events = self._cycle_events(reference.cycle_id)
        decision = self._decision_payload(events)
        if decision["classification"] not in ("buy", "sell"):
            raise LifecycleError("abstention/unavailable cycles cannot have approvals")
        self._require_after_decision(events, reference.occurred_at, "approval occurred_at")
        prior = [
            item.payload
            for item in events
            if item.event_type == "approval_reference"
            and item.payload["reference_id"] == reference.reference_id
        ]
        if any(
            item["ticket_hash"] != reference.ticket_hash
            or item["authority_kind"] != reference.authority_kind
            for item in prior
        ):
            raise LifecycleError("approval reference identity changed across lifecycle states")

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, reference.cycle_id)
            same_reference = [
                payload
                for kind, _, payload in payloads
                if kind == "approval_reference"
                and payload["reference_id"] == reference.reference_id
            ]
            if any(
                item["ticket_hash"] != reference.ticket_hash
                or item["authority_kind"] != reference.authority_kind
                for item in same_reference
            ):
                raise LifecycleError(
                    "approval reference identity changed across lifecycle states"
                )

        return self._append(
            event_type="approval_reference",
            cycle_id=reference.cycle_id,
            semantic_key=f"{reference.reference_id}:{reference.state.value}",
            idempotency_key=idempotency_key,
            occurred_at=reference.occurred_at,
            payload=reference,
            locked_validator=validate,
        )

    def record_execution(
        self, reference: ExecutionReference, *, idempotency_key: str
    ) -> LedgerEvent:
        if not isinstance(reference, ExecutionReference):
            raise TypeError("reference must be ExecutionReference")
        events = self._cycle_events(reference.cycle_id)
        decision = self._decision_payload(events)
        if decision["classification"] not in ("buy", "sell"):
            raise LifecycleError("abstention/unavailable cycles cannot have execution")
        self._require_after_decision(events, reference.occurred_at, "execution occurred_at")
        prior = [
            item.payload
            for item in events
            if item.event_type == "execution_reference"
            and item.payload["command_id"] == reference.command_id
        ]
        if any(
            tuple(item["client_order_ids"]) != reference.client_order_ids
            for item in prior
        ):
            raise LifecycleError("execution client-order identity changed across states")

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, reference.cycle_id)
            same_command = [
                payload
                for kind, _, payload in payloads
                if kind == "execution_reference"
                and payload["command_id"] == reference.command_id
            ]
            if any(
                tuple(item["client_order_ids"]) != reference.client_order_ids
                for item in same_command
            ):
                raise LifecycleError(
                    "execution client-order identity changed across lifecycle states"
                )

        return self._append(
            event_type="execution_reference",
            cycle_id=reference.cycle_id,
            semantic_key=f"{reference.command_id}:{reference.state.value}",
            idempotency_key=idempotency_key,
            occurred_at=reference.occurred_at,
            payload=reference,
            locked_validator=validate,
        )

    def record_recovery_execution(
        self,
        reference: RecoveryExecutionReference,
        *,
        idempotency_key: str,
    ) -> LedgerEvent:
        if not isinstance(reference, RecoveryExecutionReference):
            raise TypeError("reference must be RecoveryExecutionReference")
        events = self._cycle_events(reference.cycle_id)
        self._require_after_decision(
            events, reference.occurred_at, "recovery execution occurred_at"
        )
        if not any(
            item.event_type == "execution_reference"
            and item.payload["command_id"] == reference.parent_command_id
            for item in events
        ):
            raise LifecycleError(
                "recovery execution has no parent execution lifecycle reference"
            )
        prior = [
            item.payload
            for item in events
            if item.event_type == "recovery_execution_reference"
            and item.payload["recovery_command_id"]
            == reference.recovery_command_id
        ]
        if any(
            item["parent_command_id"] != reference.parent_command_id
            or item["kind"] != reference.kind
            or item["recovery_record_hash"] != reference.recovery_record_hash
            or tuple(item["client_order_ids"]) != reference.client_order_ids
            for item in prior
        ):
            raise LifecycleError(
                "recovery execution identity changed across observations"
            )

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, reference.cycle_id)
            if not any(
                kind == "execution_reference"
                and payload["command_id"] == reference.parent_command_id
                for kind, _, payload in payloads
            ):
                raise LifecycleError(
                    "recovery execution lost its parent lifecycle reference"
                )
            same = [
                payload
                for kind, _, payload in payloads
                if kind == "recovery_execution_reference"
                and payload["recovery_command_id"]
                == reference.recovery_command_id
            ]
            if any(
                payload["parent_command_id"] != reference.parent_command_id
                or payload["kind"] != reference.kind
                or payload["recovery_record_hash"]
                != reference.recovery_record_hash
                or tuple(payload["client_order_ids"])
                != reference.client_order_ids
                for payload in same
            ):
                raise LifecycleError(
                    "recovery execution identity changed concurrently"
                )

        return self._append(
            event_type="recovery_execution_reference",
            cycle_id=reference.cycle_id,
            semantic_key=reference.recovery_command_id,
            idempotency_key=idempotency_key,
            occurred_at=reference.occurred_at,
            payload=reference,
            locked_validator=validate,
        )

    def record_fill(self, fill: VenueFill, *, idempotency_key: str) -> LedgerEvent:
        if not isinstance(fill, VenueFill):
            raise TypeError("fill must be VenueFill")
        events = self._cycle_events(fill.cycle_id)
        self._require_after_decision(events, fill.venue_occurred_at, "fill occurred_at")
        matching_commands = {
            item.payload["command_id"]
            for item in events
            if item.event_type == "execution_reference"
        }
        if fill.command_id not in matching_commands:
            raise LifecycleError("fill command_id has no execution lifecycle reference")
        decision = self._decision_payload(events)
        matching_client_ids = {
            client_id
            for item in events
            if item.event_type == "execution_reference"
            and item.payload["command_id"] == fill.command_id
            for client_id in item.payload["client_order_ids"]
        }
        matching_client_ids.update(
            client_id
            for item in events
            if item.event_type == "recovery_execution_reference"
            and item.payload["parent_command_id"] == fill.command_id
            for client_id in item.payload["client_order_ids"]
        )
        if fill.client_order_id not in matching_client_ids:
            raise LifecycleError("fill client_order_id is not bound to its command")
        decision_side = DecisionClass(decision["classification"])
        expected_side = (
            decision_side
            if fill.role is FillRole.ENTRY
            else (
                DecisionClass.SELL
                if decision_side is DecisionClass.BUY
                else DecisionClass.BUY
            )
        )
        if fill.side is not expected_side:
            raise LifecycleError("fill side is inconsistent with its entry/exit role")
        settlement_asset = decision["bracket"]["settlement_asset"]
        if fill.fee_asset != settlement_asset:
            raise LifecycleError("fill fee asset must match decision settlement asset")

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, fill.cycle_id)
            closes = [
                payload for kind, _, payload in payloads if kind == "close_outcome"
            ]
            if closes:
                completed_at = _parse_iso(
                    closes[-1]["observation"]["completed_at"], "completed_at"
                )
                if fill.venue_occurred_at > completed_at:
                    raise LifecycleError(
                        "post-close supplemental fill must have occurred by the close"
                    )
            commands = {
                payload["command_id"]
                for kind, _, payload in payloads
                if kind == "execution_reference"
            }
            if fill.command_id not in commands:
                raise LifecycleError("fill command_id has no execution lifecycle reference")
            client_ids = {
                client_id
                for kind, _, payload in payloads
                if kind == "execution_reference"
                and payload["command_id"] == fill.command_id
                for client_id in payload["client_order_ids"]
            }
            client_ids.update(
                client_id
                for kind, _, payload in payloads
                if kind == "recovery_execution_reference"
                and payload["parent_command_id"] == fill.command_id
                for client_id in payload["client_order_ids"]
            )
            if fill.client_order_id not in client_ids:
                raise LifecycleError("fill client_order_id is not bound to its command")
            persisted_fills = [
                payload for kind, _, payload in payloads if kind == "venue_fill"
            ]
            entry_quantity = _sum_exact(
                (
                    Decimal(payload["quantity"])
                    for payload in persisted_fills
                    if payload["role"] == "entry"
                ),
            )
            exit_quantity = _sum_exact(
                (
                    Decimal(payload["quantity"])
                    for payload in persisted_fills
                    if payload["role"] in ("exit", "protection")
                ),
            )
            if fill.role is FillRole.ENTRY:
                entry_quantity = _add_exact(entry_quantity, fill.quantity)
            else:
                exit_quantity = _add_exact(exit_quantity, fill.quantity)
            planned_quantity = Decimal(decision["bracket"]["quantity"])
            if not closes and entry_quantity > planned_quantity:
                raise LifecycleError("entry fills exceed the proposed bracket quantity")
            if not closes and exit_quantity > entry_quantity:
                raise LifecycleError("exit fills exceed recorded entry fills")

        return self._append(
            event_type="venue_fill",
            cycle_id=fill.cycle_id,
            semantic_key=domain_hash(
                FILL_NATURAL_KEY_DOMAIN,
                {
                    "venue": decision["venue"],
                    "environment": decision["environment"],
                    "order_id": fill.order_id,
                    "fill_id": fill.fill_id,
                },
            ),
            idempotency_key=idempotency_key,
            occurred_at=fill.venue_occurred_at,
            payload=fill,
            locked_validator=validate,
        )

    def record_funding(
        self, payment: FundingPayment, *, idempotency_key: str
    ) -> LedgerEvent:
        if not isinstance(payment, FundingPayment):
            raise TypeError("payment must be FundingPayment")
        events = self._cycle_events(payment.cycle_id)
        self._require_after_decision(events, payment.occurred_at, "funding occurred_at")
        if not any(item.event_type == "execution_reference" for item in events):
            raise LifecycleError("funding requires an execution lifecycle reference")
        decision = self._decision_payload(events)
        if payment.asset != decision["bracket"]["settlement_asset"]:
            raise LifecycleError("funding asset must match decision settlement asset")

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, payment.cycle_id)
            closes = [
                payload for kind, _, payload in payloads if kind == "close_outcome"
            ]
            if closes:
                completed_at = _parse_iso(
                    closes[-1]["observation"]["completed_at"], "completed_at"
                )
                if payment.occurred_at > completed_at:
                    raise LifecycleError(
                        "post-close supplemental funding must have occurred by the close"
                    )
            if not any(kind == "execution_reference" for kind, _, _ in payloads):
                raise LifecycleError("funding requires an execution lifecycle reference")

        return self._append(
            event_type="funding_payment",
            cycle_id=payment.cycle_id,
            semantic_key=payment.funding_id,
            idempotency_key=idempotency_key,
            occurred_at=payment.occurred_at,
            payload=payment,
            locked_validator=validate,
        )

    def record_market_path(
        self, path: MarketPathEvidence, *, idempotency_key: str
    ) -> LedgerEvent:
        """Commit source bars and derive actual MAE/MFE when entry fills exist."""

        if not isinstance(path, MarketPathEvidence):
            raise TypeError("path must be MarketPathEvidence")
        replay = self._event_by_idempotency_key(idempotency_key)
        if replay is not None:
            if (
                replay.event_type == "market_path"
                and replay.payload["market_path"] == canonical_data(path)
            ):
                return replay
            raise IdempotencyConflict(
                f"idempotency key {idempotency_key!r} is bound to different content"
            )
        events = self._cycle_events(path.cycle_id)
        self._require_after_decision(events, path.captured_at, "path captured_at")
        decision_time = events[0].occurred_at
        if path.window_started_at < decision_time:
            raise LifecycleError("outcome/counterfactual path bars must not precede the decision")
        decision = self._decision_payload(events)
        path_data = canonical_data(path)
        payload: dict[str, Any] = {
            "market_path": path_data,
            "path_hash": domain_hash(MARKET_PATH_DOMAIN, path_data),
            "excursion_derivation_version": "filled-entry-extrema-r/v1",
            "actual_excursion": None,
            "entry_fill_event_hashes": tuple(
                item.event_hash
                for item in events
                if item.event_type == "venue_fill" and item.payload["role"] == "entry"
            ),
        }
        entry_fills = [
            item.payload
            for item in events
            if item.event_type == "venue_fill" and item.payload["role"] == "entry"
        ]
        if entry_fills:
            earliest_entry_at = min(
                _parse_iso(item["venue_occurred_at"], "venue_occurred_at")
                for item in entry_fills
            )
            if path.window_started_at != earliest_entry_at:
                raise LifecycleError(
                    "executed-trade market path must start exactly at the first entry fill"
                )
            total_quantity = _sum_exact(
                Decimal(item["quantity"]) for item in entry_fills
            )
            weighted = _sum_exact(
                _multiply_exact(Decimal(item["price"]), Decimal(item["quantity"]))
                for item in entry_fills
            )
            entry = _ratio(weighted, total_quantity)
            stop = Decimal(decision["bracket"]["stop_price"])
            risk_unit = abs(_subtract_exact(entry, stop))
            if risk_unit == 0:
                raise LifecycleError("filled entry equals stop; excursion R is undefined")
            highs = [bar.high for bar in path.bars]
            lows = [bar.low for bar in path.bars]
            if decision["classification"] == "buy":
                adverse = max(Decimal(0), _subtract_exact(entry, min(lows)))
                favorable = max(Decimal(0), _subtract_exact(max(highs), entry))
            else:
                adverse = max(Decimal(0), _subtract_exact(max(highs), entry))
                favorable = max(Decimal(0), _subtract_exact(entry, min(lows)))
            payload["actual_excursion"] = {
                "entry_price": entry,
                "risk_per_unit": risk_unit,
                "mae_r": _ratio(adverse, risk_unit),
                "mfe_r": _ratio(favorable, risk_unit),
            }

        entry_basis = tuple(payload["entry_fill_event_hashes"])

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, path.cycle_id)
            closes = [
                payload for kind, _, payload in payloads if kind == "close_outcome"
            ]
            if closes:
                completed_at = _parse_iso(
                    closes[-1]["observation"]["completed_at"], "completed_at"
                )
                if path.window_ended_at != completed_at:
                    raise LifecycleError(
                        "post-close market path must cover the exact entry-to-close window"
                    )
            current_basis = tuple(
                event_hash
                for kind, event_hash, item_payload in payloads
                if kind == "venue_fill" and item_payload["role"] == "entry"
            )
            if current_basis != entry_basis:
                raise LifecycleError("entry-fill evidence changed while deriving market path")

        return self._append(
            event_type="market_path",
            cycle_id=path.cycle_id,
            semantic_key=path.path_id,
            idempotency_key=idempotency_key,
            occurred_at=path.captured_at,
            payload=payload,
            locked_validator=validate,
        )

    def record_close(
        self, close: CloseObservation, *, idempotency_key: str
    ) -> LedgerEvent:
        """Record a close and derive fees, funding, net P&L, and realized R."""

        if not isinstance(close, CloseObservation):
            raise TypeError("close must be CloseObservation")
        replay = self._event_by_idempotency_key(idempotency_key)
        if replay is not None:
            if (
                replay.event_type == "close_outcome"
                and replay.payload["observation"] == canonical_data(close)
            ):
                return replay
            raise IdempotencyConflict(
                f"idempotency key {idempotency_key!r} is bound to different content"
            )
        events = self._cycle_events(close.cycle_id)
        self._require_after_decision(events, close.completed_at, "close completed_at")
        decision = self._decision_payload(events)
        if decision["classification"] not in ("buy", "sell"):
            raise LifecycleError("only a position decision can close")
        if not any(
            item.event_type == "venue_fill" and item.payload["role"] == "entry"
            for item in events
        ):
            raise LifecycleError("close requires at least one entry fill")
        fill_command_ids = {
            item.payload["command_id"]
            for item in events
            if item.event_type == "venue_fill"
        }
        reconciled_command_ids = {
            item.payload["command_id"]
            for item in events
            if item.event_type == "execution_reference"
            and item.payload["state"] == "reconciled"
        }
        if not fill_command_ids.issubset(reconciled_command_ids):
            raise LifecycleError(
                "close requires reconciliation of every command owning a fill"
            )
        entry_fill_hashes = tuple(
            item.event_hash
            for item in events
            if item.event_type == "venue_fill" and item.payload["role"] == "entry"
        )
        eligible_paths = tuple(
            item
            for item in events
            if (
            item.event_type == "market_path"
            and item.payload["actual_excursion"] is not None
            and tuple(item.payload["entry_fill_event_hashes"]) == entry_fill_hashes
            and item.payload["market_path"]["window_ended_at"]
            == _iso(close.completed_at)
            )
        )
        if not eligible_paths:
            raise LifecycleError(
                "close requires MAE/MFE over the exact entry-to-close window and complete fills"
            )
        selected_excursion_path = eligible_paths[-1]
        settlement_asset = decision["bracket"]["settlement_asset"]
        if close.pnl_asset != settlement_asset:
            raise LifecycleError("close P&L asset must match decision settlement asset")
        factual_times = tuple(
            item.occurred_at
            for item in events
            if item.event_type in ("venue_fill", "funding_payment")
        )
        if factual_times and close.completed_at < max(factual_times):
            raise LifecycleError("close completed_at precedes recorded trade evidence")
        fees = _sum_exact(
            Decimal(item.payload["fee"])
            for item in events
            if item.event_type == "venue_fill"
        )
        funding = _sum_exact(
            Decimal(item.payload["amount"])
            for item in events
            if item.event_type == "funding_payment"
        )
        net_pnl = _add_exact(_subtract_exact(close.gross_pnl, fees), funding)
        entry_quantity = _sum_exact(
            (
                Decimal(item.payload["quantity"])
                for item in events
                if item.event_type == "venue_fill" and item.payload["role"] == "entry"
            ),
        )
        exit_quantity = _sum_exact(
            (
                Decimal(item.payload["quantity"])
                for item in events
                if item.event_type == "venue_fill"
                and item.payload["role"] in ("exit", "protection")
            ),
        )
        if exit_quantity != entry_quantity:
            raise LifecycleError("close requires reconciled flat fill quantities")
        planned_risk_amount = Decimal(decision["bracket"]["risk_amount"])
        planned_quantity = Decimal(decision["bracket"]["quantity"])
        risk_amount = _multiply_exact(
            planned_risk_amount, _ratio(entry_quantity, planned_quantity)
        )
        payload = {
            "observation": close,
            "total_fees": fees,
            "total_funding": funding,
            "net_pnl": net_pnl,
            "realized_r": _ratio(net_pnl, risk_amount),
            "realized_r_risk_basis_amount": risk_amount,
            "pnl_derivation_version": "gross-minus-fees-plus-funding/v1",
            "realized_r_derivation_version": "net-pnl-over-filled-share-of-planned-risk/v1",
            "excursion_path_event_hash": selected_excursion_path.event_hash,
            "excursion_path_hash": selected_excursion_path.payload["path_hash"],
            "gross_pnl_fill_basis_hashes": tuple(
                item.event_hash for item in events if item.event_type == "venue_fill"
            ),
            "basis_event_hashes": tuple(
                item.event_hash
                for item in events
                if item.event_type in ("venue_fill", "funding_payment", "market_path")
            ),
        }

        basis = tuple(payload["basis_event_hashes"])

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, close.cycle_id)
            current_basis = tuple(
                event_hash
                for kind, event_hash, _ in payloads
                if kind in ("venue_fill", "funding_payment", "market_path")
            )
            if current_basis != basis:
                raise LifecycleError("trade evidence changed while deriving close outcome")
            if any(kind == "close_outcome" for kind, _, _ in payloads):
                raise DuplicateConflict("cycle already has a close outcome")

        return self._append(
            event_type="close_outcome",
            cycle_id=close.cycle_id,
            semantic_key=close.cycle_id,
            idempotency_key=idempotency_key,
            occurred_at=close.completed_at,
            payload=payload,
            locked_validator=validate,
        )

    def record_close_pnl_correction(
        self,
        correction: ClosePnlCorrection,
        *,
        idempotency_key: str,
    ) -> LedgerEvent:
        """Append a versioned gross-P&L correction bound to current fill evidence."""

        if not isinstance(correction, ClosePnlCorrection):
            raise TypeError("correction must be ClosePnlCorrection")
        replay = self._event_by_idempotency_key(idempotency_key)
        if replay is not None:
            if (
                replay.event_type == "close_pnl_correction"
                and replay.payload["observation"] == canonical_data(correction)
            ):
                return replay
            raise IdempotencyConflict(
                f"idempotency key {idempotency_key!r} is bound to different content"
            )
        events = self._cycle_events(correction.cycle_id)
        close_event = next(
            (item for item in events if item.event_type == "close_outcome"), None
        )
        if close_event is None:
            raise LifecycleError("close P&L correction requires a close outcome")
        completed_at = _parse_iso(
            close_event.payload["observation"]["completed_at"], "completed_at"
        )
        if correction.observed_at < completed_at:
            raise LifecycleError("close P&L correction cannot predate the close")
        decision = self._decision_payload(events)
        if correction.pnl_asset != decision["bracket"]["settlement_asset"]:
            raise LifecycleError("correction P&L asset must match decision settlement asset")
        fills = tuple(item for item in events if item.event_type == "venue_fill")
        fill_command_ids = {item.payload["command_id"] for item in fills}
        reconciled_command_ids = {
            item.payload["command_id"]
            for item in events
            if item.event_type == "execution_reference"
            and item.payload["state"] == "reconciled"
        }
        if not fill_command_ids.issubset(reconciled_command_ids):
            raise LifecycleError(
                "correction requires reconciliation of every command owning a fill"
            )
        entry_quantity = _sum_exact(
            Decimal(item.payload["quantity"])
            for item in fills
            if item.payload["role"] == "entry"
        )
        exit_quantity = _sum_exact(
            Decimal(item.payload["quantity"])
            for item in fills
            if item.payload["role"] in ("exit", "protection")
        )
        if not entry_quantity or entry_quantity != exit_quantity:
            raise LifecycleError("correction requires reconciled flat fill quantities")
        fees = _sum_exact(Decimal(item.payload["fee"]) for item in fills)
        funding_events = tuple(
            item for item in events if item.event_type == "funding_payment"
        )
        funding = _sum_exact(
            Decimal(item.payload["amount"]) for item in funding_events
        )
        net_pnl = _add_exact(_subtract_exact(correction.gross_pnl, fees), funding)
        risk_basis = _multiply_exact(
            Decimal(decision["bracket"]["risk_amount"]),
            _ratio(entry_quantity, Decimal(decision["bracket"]["quantity"])),
        )
        prior_corrections = tuple(
            item for item in events if item.event_type == "close_pnl_correction"
        )
        supersedes = prior_corrections[-1] if prior_corrections else close_event
        fill_basis = tuple(item.event_hash for item in fills)
        net_basis = tuple(
            item.event_hash
            for item in events
            if item.event_type in ("venue_fill", "funding_payment")
        )
        payload = {
            "observation": correction,
            "close_event_hash": close_event.event_hash,
            "supersedes_event_hash": supersedes.event_hash,
            "gross_pnl_fill_basis_hashes": fill_basis,
            "net_pnl_basis_event_hashes": net_basis,
            "total_fees": fees,
            "total_funding": funding,
            "net_pnl": net_pnl,
            "realized_r_risk_basis_amount": risk_basis,
            "realized_r": _ratio(net_pnl, risk_basis),
            "derivation_version": "corrected-gross-current-costs-filled-risk/v1",
        }

        def validate(connection: sqlite3.Connection) -> None:
            payloads = self._locked_payloads(connection, correction.cycle_id)
            current_fill_basis = tuple(
                event_hash
                for kind, event_hash, _ in payloads
                if kind == "venue_fill"
            )
            current_net_basis = tuple(
                event_hash
                for kind, event_hash, _ in payloads
                if kind in ("venue_fill", "funding_payment")
            )
            current_superseded = tuple(
                event_hash
                for kind, event_hash, _ in payloads
                if kind in ("close_outcome", "close_pnl_correction")
            )[-1]
            if current_fill_basis != fill_basis or current_net_basis != net_basis:
                raise LifecycleError(
                    "trade evidence changed while deriving close P&L correction"
                )
            if current_superseded != supersedes.event_hash:
                raise LifecycleError("close P&L correction supersession changed")

        return self._append(
            event_type="close_pnl_correction",
            cycle_id=correction.cycle_id,
            semantic_key=domain_hash(
                CLOSE_CORRECTION_KEY_DOMAIN,
                {
                    "cycle_id": correction.cycle_id,
                    "correction_id": correction.correction_id,
                },
            ),
            idempotency_key=idempotency_key,
            occurred_at=correction.observed_at,
            payload=payload,
            locked_validator=validate,
        )

    def record_counterfactual(
        self,
        cycle_id: str,
        path_id: str,
        spec: CounterfactualSpec,
        *,
        idempotency_key: str,
    ) -> LedgerEvent:
        """Derive a conservative bracket counterfactual from committed bars.

        The caller supplies parameters, never an outcome.  If stop and target
        are touched in the same bar, the stop is selected because intrabar
        ordering is unknowable from OHLC evidence.
        """

        cycle_id = _text(cycle_id, "cycle_id")
        path_id = _text(path_id, "path_id")
        if not isinstance(spec, CounterfactualSpec):
            raise TypeError("spec must be CounterfactualSpec")
        events = self._cycle_events(cycle_id)
        path_event = next(
            (
                item
                for item in events
                if item.event_type == "market_path"
                and item.payload["market_path"]["path_id"] == path_id
            ),
            None,
        )
        if path_event is None:
            raise LifecycleError("counterfactual requires an immutable market path")
        raw_bars = path_event.payload["market_path"]["bars"][: spec.max_bars]
        if not raw_bars:
            raise LifecycleError("counterfactual market path is empty")
        risk = abs(_subtract_exact(spec.entry_price, spec.stop_price))
        target_r = _ratio(
            abs(_subtract_exact(spec.target_price, spec.entry_price)), risk
        )
        outcome = "not_entered"
        gross_r: Decimal | None = None
        entry_bar_opened_at: str | None = None
        entry_bar_closed_at: str | None = None
        entry_time_precision: str | None = None
        exit_bar_opened_at: str | None = None
        exit_bar_closed_at: str | None = None
        exit_time_precision: str | None = None
        entered = False
        same_bar_conservative_stop = False
        same_bar_entry_ambiguity = False
        same_bar_target_ignored = False
        bars_evaluated = 0
        for index, bar in enumerate(raw_bars):
            bars_evaluated = index + 1
            high = Decimal(bar["high"])
            low = Decimal(bar["low"])
            opened = Decimal(bar["open"])
            closed = Decimal(bar["close"])
            entered_at_open = False
            entered_this_bar = False
            if not entered:
                if spec.entry_rule is CounterfactualEntryRule.WINDOW_OPEN:
                    if index != 0:
                        raise AssertionError("window-open entry must be evaluated on first bar")
                    if opened != spec.entry_price:
                        raise LifecycleError(
                            "window_open counterfactual entry must equal the first bar open"
                        )
                    entered = True
                    entered_this_bar = True
                    entered_at_open = True
                    entry_bar_opened_at = bar["opened_at"]
                    entry_bar_closed_at = bar["closed_at"]
                    entry_time_precision = "exact_window_open"
                else:
                    if not low <= spec.entry_price <= high:
                        continue
                    entered = True
                    entered_this_bar = True
                    entry_bar_opened_at = bar["opened_at"]
                    entry_bar_closed_at = bar["closed_at"]
                    entered_at_open = opened == spec.entry_price
                    entry_time_precision = (
                        "exact_bar_open" if entered_at_open else "bar_interval"
                    )
                    same_bar_entry_ambiguity = not entered_at_open
            if spec.side is DecisionClass.BUY:
                stop_hit = low <= spec.stop_price
                target_hit = high >= spec.target_price
                close_proves_post_entry_target = closed >= spec.target_price
            else:
                stop_hit = high >= spec.stop_price
                target_hit = low <= spec.target_price
                close_proves_post_entry_target = closed <= spec.target_price
            if stop_hit:
                outcome = "stop"
                gross_r = Decimal(-1)
                exit_bar_opened_at = bar["opened_at"]
                exit_bar_closed_at = bar["closed_at"]
                exit_time_precision = "bar_interval"
                same_bar_conservative_stop = target_hit
                break
            if target_hit:
                if (
                    entered_this_bar
                    and not entered_at_open
                    and not close_proves_post_entry_target
                ):
                    same_bar_target_ignored = True
                    continue
                outcome = "target"
                gross_r = target_r
                exit_bar_opened_at = bar["opened_at"]
                exit_bar_closed_at = bar["closed_at"]
                exit_time_precision = "bar_interval"
                break
        if not entered:
            gross_r = Decimal(0)
            assumed_cost_r = Decimal(0)
        elif gross_r is None:
            outcome = "time_mark"
            final_close = Decimal(raw_bars[-1]["close"])
            move = _subtract_exact(final_close, spec.entry_price)
            if spec.side is DecisionClass.SELL:
                move = -move
            gross_r = _ratio(move, risk)
            exit_bar_opened_at = raw_bars[-1]["opened_at"]
            exit_bar_closed_at = raw_bars[-1]["closed_at"]
            exit_time_precision = "exact_bar_close"
            assumed_cost_r = spec.cost_r
        else:
            assumed_cost_r = spec.cost_r
        payload = {
            "spec": spec,
            "path_id": path_id,
            "path_hash": path_event.payload["path_hash"],
            "market_source_snapshot_hash": path_event.payload["market_path"][
                "source_snapshot_hash"
            ],
            "derivation_version": COUNTERFACTUAL_DERIVATION_VERSION,
            "outcome": outcome,
            "entered": entered,
            "entry_bar_opened_at": entry_bar_opened_at,
            "entry_bar_closed_at": entry_bar_closed_at,
            "entry_time_precision": entry_time_precision,
            "gross_r": gross_r,
            "assumed_cost_r_applied": assumed_cost_r,
            "net_r_after_assumed_cost": _subtract_exact(gross_r, assumed_cost_r),
            "exit_bar_opened_at": exit_bar_opened_at,
            "exit_bar_closed_at": exit_bar_closed_at,
            "exit_time_precision": exit_time_precision,
            "bars_evaluated": bars_evaluated,
            "same_bar_conservative_stop": same_bar_conservative_stop,
            "same_bar_entry_ambiguity": same_bar_entry_ambiguity,
            "same_bar_target_ignored": same_bar_target_ignored,
            "interpretation": "counterfactual_description_not_causal_evidence",
        }
        return self._append(
            event_type="counterfactual",
            cycle_id=cycle_id,
            semantic_key=domain_hash(
                COUNTERFACTUAL_KEY_DOMAIN,
                {
                    "cycle_id": cycle_id,
                    "scenario_id": spec.scenario_id,
                    "scenario_version": spec.scenario_version,
                    "entry_rule": spec.entry_rule,
                },
            ),
            idempotency_key=idempotency_key,
            occurred_at=path_event.occurred_at,
            payload=payload,
        )
